CARD_IDS = sorted(CARDS)
PAIR_IDS = sorted(PAIRS)

def revise(grammar, pairs):
    for card_id, (meaning, connection, usage, limits) in CARDS.items():
        card = grammar[str(card_id)]
        card['t'] = f'{meaning}\nПриєднання: {connection}\n【用法】 {usage}\n【制約】 {limits}'
        if card_id in DEFINITIONS:
            card['m'] = DEFINITIONS[card_id]
    for (card_id, example_index), translation in TRANSLATIONS.items():
        grammar[str(card_id)]['exampleTranslations'][example_index] = translation
    for index, (shared, connection, difference, ja1, uk1, ja2, uk2, substitution) in PAIRS.items():
        pairs[index][2] = (
            f'【共通点】\n{shared}\n【接続】\n{connection}\n【違い】\n{difference}'
            f'\n【例文】\n{ja1} — {uk1}\n{ja2} — {uk2}\n【置き換え】\n{substitution}'
        )
